css:
:root { --lunar-edge: rgba(199,203,209,0.28); }
body { background: radial-gradient(ellipse at 50% -18%, rgba(164,175,190,0.14), transparent 45%), #15171a !important; }
[data-slot="sidebar"] { background: linear-gradient(180deg,#1b1e22,#15171a) !important; border-right-color: rgba(199,203,209,0.22) !important; }
[data-slot="sidebar-inner"] { background: linear-gradient(180deg,rgba(255,255,255,0.035),transparent 38%) !important; }
[data-thread-item] { border: 1px solid transparent !important; border-radius: 10px !important; transition: 160ms ease !important; }
[data-thread-item] [data-sidebar-row][data-testid="sidebar-row-folder"] { padding-inline-start: 1.4375rem !important; }
[data-thread-item]:hover { background: rgba(199,203,209,0.09) !important; border-color: rgba(199,203,209,0.17) !important; border-radius: 10px !important; }
[data-thread-item][aria-current="page"],[data-thread-item][data-active="true"] { background: linear-gradient(90deg,rgba(199,203,209,0.18),rgba(199,203,209,0.06)) !important; border-color: rgba(199,203,209,0.25) !important; box-shadow: inset 2px 0 #c7cbd1,inset 0 1px rgba(255,255,255,0.06) !important; }
[data-chat-header] { background: linear-gradient(180deg,rgba(39,43,49,0.94),rgba(27,30,34,0.92)) !important; border-color: var(--lunar-edge) !important; backdrop-filter: blur(18px) !important; }
[data-workspace-area="conversation"] { background: radial-gradient(ellipse at 50% 0%,rgba(145,157,174,0.09),transparent 43%),#15171a !important; }
[data-user-message-bubble] { background: linear-gradient(145deg,#30353c,#252a30) !important; border: 1px solid rgba(199,203,209,0.28) !important; box-shadow: 0 9px 28px rgba(4,6,9,0.25),inset 0 1px rgba(255,255,255,0.08) !important; }
.chat-markdown-codeblock { background: linear-gradient(135deg,#171a1e,#20242a) !important; border: 1px solid rgba(199,203,209,0.22) !important; box-shadow: inset 0 1px rgba(255,255,255,0.04),0 10px 30px rgba(0,0,0,0.18) !important; }
[data-slot="composer-host"] { border: 1px solid rgba(199,203,209,0.34) !important; border-radius: 16px !important; box-shadow: 0 16px 46px rgba(4,6,9,0.35),inset 0 1px rgba(255,255,255,0.08) !important; }
[data-slot="composer-host"]:focus-within { border-color: rgba(226,230,235,0.72) !important; box-shadow: 0 17px 52px rgba(4,6,9,0.4),0 0 0 3px rgba(199,203,209,0.1),inset 0 1px rgba(255,255,255,0.1) !important; }
[data-slot="button"] { transition: 160ms ease !important; }
[data-slot="button"]:active { transform: translateY(1px) !important; }
[data-slot="input"],[data-slot="select-trigger"] { background: rgba(20,23,27,0.72) !important; border-color: rgba(199,203,209,0.24) !important; }
[data-slot="sidebar"] :has(> [data-slot="input"]) { background: transparent !important; box-shadow: none !important; border-radius: 0 !important; }
[data-slot="sidebar"] [data-slot="input"] { background: rgba(20,23,27,0.72) !important; border: 1px solid rgba(199,203,209,0.24) !important; border-radius: 10px !important; padding-left: 14px !important; box-shadow: none !important; }
[data-slot="sidebar"] [data-slot="input"]:focus { outline: none !important; border-color: rgba(199,203,209,0.48) !important; box-shadow: 0 0 0 3px rgba(199,203,209,0.08) !important; }
svg.lucide { stroke-width: 1.7 !important; stroke-linecap: round !important; stroke-linejoin: round !important; }
::selection { color: #17191c !important; background: #c7cbd1 !important; }
::-webkit-scrollbar-thumb { background: rgba(199,203,209,0.24) !important; border: 3px solid transparent !important; background-clip: padding-box !important; border-radius: 999px !important; }
::-webkit-scrollbar-thumb:hover { background: rgba(199,203,209,0.44) !important; border: 2px solid transparent !important; background-clip: padding-box !important; border-radius: 999px !important; }
